pub enum BinderAdmission {
    BindersAdmitted {
        locals: Rc<HashMap<Symbol, Symbol>>,
    },
    BinderDuplicateInFrame {
        binder: Symbol,
    },
    BinderHidesVisibleValue {
        binder: Symbol,
    },
}

pub fn admit_value_binders(names: Rc<Vec<Symbol>>, outer: Rc<Scope>) -> Rc<BinderAdmission> {
    names.iter().cloned().fold(Rc::new(BinderAdmission::BindersAdmitted {
    locals: v1_rt::rc_empty_map::<_, _>(),
}), |acc: Rc<BinderAdmission>, name: Symbol| match (*acc).clone() {
    BinderAdmission::BinderDuplicateInFrame { binder: b, .. } => Rc::new(BinderAdmission::BinderDuplicateInFrame {
    binder: b.clone(),
}),
    BinderAdmission::BinderHidesVisibleValue { binder: b, .. } => Rc::new(BinderAdmission::BinderHidesVisibleValue {
    binder: b.clone(),
}),
    BinderAdmission::BindersAdmitted { locals: m, .. } => match v1_rt::lookup(&m, name.clone()) {
    Some(_) => Rc::new(BinderAdmission::BinderDuplicateInFrame {
    binder: name.clone(),
}),
    std::option::Option::None => admit_one_value_binder(m.clone(), name.clone(), outer.clone()),
},
})
}

pub fn admit_one_value_binder(locals: Rc<HashMap<Symbol, Symbol>>, name: std::string::String, outer: Rc<Scope>) -> Rc<BinderAdmission> {
    if crate::v2_std_anonymous_binder::is_anonymous_param_label(name.clone()) {
        Rc::new(BinderAdmission::BindersAdmitted {
    locals: v1_rt::rc_map_insert(locals.clone(), name.clone(), name.clone()),
})
    } else {
        admit_one_named_value_binder(locals.clone(), name.clone(), outer)
    }
}

pub fn admit_one_named_value_binder(locals: Rc<HashMap<Symbol, Symbol>>, name: std::string::String, outer: Rc<Scope>) -> Rc<BinderAdmission> {
    match (*lookup_chain(outer, name.clone())).clone() {
    Outcome::Rejected { diagnostics: _, .. } => Rc::new(BinderAdmission::BindersAdmitted {
    locals: v1_rt::rc_map_insert(locals.clone(), name.clone(), name.clone()),
}),
    Outcome::Accepted { value: bound, .. } => match (*bound.clone()).clone() {
    ScopeBinding::BoundInFrame { .. } => Rc::new(BinderAdmission::BinderHidesVisibleValue {
    binder: name.clone(),
}),
    ScopeBinding::BoundAtRoot { canonical: _, .. } => Rc::new(BinderAdmission::BindersAdmitted {
    locals: v1_rt::rc_map_insert(locals.clone(), name.clone(), name.clone()),
}),
    ScopeBinding::ScopeUnbound => Rc::new(BinderAdmission::BindersAdmitted {
    locals: v1_rt::rc_map_insert(locals.clone(), name.clone(), name.clone()),
}),
},
}
}

