pub fn bind_binder_name_list(n: Rc<Node>) -> Rc<Vec<Symbol>> {
    match (*n.kind.clone()).clone() {
    NodeKind::ComputationNode { behavior: Behavior::Bind, .. } => if (crate::v2_std_node::positional_child_count(n.children.clone()) == 3) {
        match crate::v2_std_node::positional_edges(n.children.clone()).first().cloned() {
    Some(e0) => atom_name_list(e0.target.clone()),
    std::option::Option::None => Rc::new(vec![]),
}
    } else {
        Rc::new(vec![])
    },
    NodeKind::TypeNode { connective: _, .. } => Rc::new(vec![]),
    NodeKind::ComputationNode { behavior: _, .. } => Rc::new(vec![]),
}
}

pub fn atom_name_list(root: Rc<Node>) -> Rc<Vec<Symbol>> {
    crate::v2_std_node::fold_node(root, Rc::new(NodeFold {
    init: { Rc::new(move |n0| match (*n0.kind.clone()).clone() {
    NodeKind::TypeNode { connective: ref __rc_connective, .. } => { match __rc_connective.as_ref() {
    Connective::Atom { identity: sym, .. } => Rc::new(vec![sym.clone()]),
    _ => Rc::new(vec![]),
} },
    NodeKind::ComputationNode { behavior: _, .. } => Rc::new(vec![]),
}) },
    step: { Rc::new(move |acc, _e, child| v1_rt::concat(acc.clone(), child.clone())) },
    _phantom: std::marker::PhantomData,
}))
}

