pub fn resolve_type_decl_member_child_walk(ctx: Rc<ResolveContext>, e: Rc<Edge>) -> TypeDeclChildWalk {
    match (*ctx.declaring.clone()).clone() {
    DeclaringPosition::DeclaringAt { path: path, .. } => if (path.clone() == ctx.namespace.module_qn.clone()) {
        crate::v2_std_symbol_index::type_decl_member_child_walk(crate::v2_std_symbol_index::type_decl_member_shape(ctx.namespace.symbol_index.clone(), crate::v2_std_qualified_name::qualified_name_snoc(path.clone(), crate::v2_std_node::label_sort_key(e.label.clone())), e.target.clone()))
    } else {
        TypeDeclChildWalk::TypeDeclChildrenInherited
    },
    DeclaringPosition::DeclaringInSpine { .. } => TypeDeclChildWalk::TypeDeclChildrenInherited,
    DeclaringPosition::NotDeclaring => TypeDeclChildWalk::TypeDeclChildrenInherited,
}
}

