pub fn resolve_declaring_across_named_edge(declaring: Rc<DeclaringPosition>, e: Rc<Edge>) -> Rc<DeclaringPosition> {
    match (*declaring.clone()).clone() {
    DeclaringPosition::DeclaringAt { path: path, .. } => if crate::v2_compiler_symbol_index_fill::symbol_index_edge_introduces_no_declarations(e.clone()) {
        Rc::new(DeclaringPosition::NotDeclaring)
    } else {
        match (*e.label.clone()).clone() {
    EdgeLabel::StructuralLabel { label: _, .. } => if (crate::v2_extdeps_languages_dag::dag_surface_module_header_metadata_edge(e.clone()) || crate::v2_std_node_query::binder_node_edge(e.clone())) {
            declaring.clone()
        } else {
            Rc::new(DeclaringPosition::DeclaringAt {
    path: crate::v2_std_qualified_name::qualified_name_snoc(path.clone(), crate::v2_std_node::label_sort_key(e.label.clone())),
})
        },
    EdgeLabel::Authored { name: name, .. } => if crate::v2_compiler_parse::parse_tree_projection_edge(name.clone()) {
            declaring.clone()
        } else {
            Rc::new(DeclaringPosition::DeclaringAt {
    path: crate::v2_std_qualified_name::qualified_name_snoc(path.clone(), name.clone()),
})
        },
    EdgeLabel::Positional => declaring.clone(),
}
    },
    DeclaringPosition::DeclaringInSpine { .. } => declaring.clone(),
    DeclaringPosition::NotDeclaring => declaring.clone(),
}
}

pub fn resolve_declaring_entering(declaring: Rc<DeclaringPosition>, n: Rc<Node>) -> Rc<DeclaringPosition> {
    match (*declaring.clone()).clone() {
    DeclaringPosition::DeclaringAt { path: path, .. } => match (*n.kind.clone()).clone() {
    NodeKind::TypeNode { connective: ref __rc_connective, .. } if matches!(__rc_connective.as_ref(), Connective::Conj) => { let Connective::Conj = __rc_connective.as_ref() else { unreachable!() }; match crate::v2_extdeps_languages_dag::namespace_graft_spine_body_optional(n.clone()) {
    Some(body) => Rc::new(DeclaringPosition::DeclaringInSpine {
    path: path.clone(),
    body: body.clone(),
}),
    std::option::Option::None => declaring.clone(),
} },
    _ => declaring.clone(),
},
    DeclaringPosition::DeclaringInSpine { path, body, .. } => if crate::v2_std_node::node_same_occurrence(n.clone(), body.clone()) {
        Rc::new(DeclaringPosition::DeclaringAt {
    path: path.clone(),
})
    } else {
        declaring.clone()
    },
    DeclaringPosition::NotDeclaring => declaring.clone(),
}
}

