#[derive(Debug, Clone, PartialEq, serde::Serialize)]
#[serde(tag = "_variant")]
pub enum ScopeBinding {
    BoundInFrame {
        canonical: Symbol,
        kind: Rc<FrameKind>,
    },
    BoundAtRoot {
        canonical: Symbol,
    },
    ScopeUnbound,
}
impl ScopeBinding {
    pub fn canonical(&self) -> Symbol {
        match self {
            ScopeBinding::BoundInFrame { canonical: __val, .. } => __val.clone(),
            ScopeBinding::BoundAtRoot { canonical: __val, .. } => __val.clone(),
            ScopeBinding::ScopeUnbound => panic!("no canonical on unit variant"),
        }
    }
}

pub fn lookup_chain(s: Rc<Scope>, name: std::string::String) -> Rc<Outcome<Rc<ScopeBinding>>> {
    stacker::maybe_grow(512 * 1024, 2 * 1024 * 1024, || {
        match (*s.clone()).clone() {
    Scope::ScopeFrame { locals: m, outer: o, kind, .. } => match (*crate::v2_std_witness::map_get_checked(m.clone(), name.clone())).clone() {
    Outcome::Accepted { value: opt, diagnostics: ref __rc_diagnostics, .. } => { let d_here = __rc_diagnostics.as_ref(); match opt.clone() {
    Some(v) => Rc::new(Outcome::Accepted {
    value: Rc::new(ScopeBinding::BoundInFrame {
    canonical: v.clone(),
    kind: kind.clone(),
}),
    diagnostics: Box::new(d_here.clone()),
}),
    std::option::Option::None => match (*lookup_chain(o.clone(), name.clone())).clone() {
    Outcome::Accepted { value: found, diagnostics: ref __rc_diagnostics, .. } => { let d_outer = __rc_diagnostics.as_ref(); Rc::new(Outcome::Accepted {
    value: found.clone(),
    diagnostics: Box::new(crate::v2_std_diagnostic::diagnostics_merge(d_here.clone(), d_outer.clone())),
}) },
    Outcome::Rejected { diagnostics: ds, .. } => Rc::new(Outcome::Rejected {
    diagnostics: crate::v2_std_diagnostic::rejected_with_pending(d_here.clone(), ds.clone()),
}),
},
} },
    Outcome::Rejected { diagnostics: ds, .. } => Rc::new(Outcome::Rejected {
    diagnostics: ds.clone(),
}),
},
    Scope::ScopeRoot { module: mod_, .. } => match (*crate::v2_std_witness::map_get_checked(mod_.bindings.clone(), name.clone())).clone() {
    Outcome::Accepted { value: opt, diagnostics: ref __rc_diagnostics, .. } => { let d = __rc_diagnostics.as_ref(); match opt.clone() {
    Some(v) => Rc::new(Outcome::Accepted {
    value: Rc::new(ScopeBinding::BoundAtRoot {
    canonical: v.clone(),
}),
    diagnostics: Box::new(d.clone()),
}),
    std::option::Option::None => Rc::new(Outcome::Accepted {
    value: Rc::new(ScopeBinding::ScopeUnbound),
    diagnostics: Box::new(d.clone()),
}),
} },
    Outcome::Rejected { diagnostics: ds, .. } => Rc::new(Outcome::Rejected {
    diagnostics: ds.clone(),
}),
},
}
    })
}

#[derive(Debug, Clone, Copy, PartialEq, Eq, PartialOrd, Ord, serde::Serialize, serde::Deserialize)]
