#[derive(Debug, Clone, PartialEq, serde::Serialize)]
pub struct ResolveRequirementScan {
    pub seen: Rc<Vec<QualifiedName>>,
    pub refusal: Option<Rc<Diagnostic>>,
}

pub fn resolve_requirement_member_refusal_optional(index: Rc<SymbolIndex>, members: Rc<Vec<Rc<Edge>>>) -> Option<Rc<Diagnostic>> {
    members.iter().cloned().fold(Rc::new(ResolveRequirementScan {
    seen: Rc::new(vec![]),
    refusal: crate::std_optional::optional_absent(),
}), |acc: Rc<ResolveRequirementScan>, e: Rc<Edge>| match acc.refusal.clone() {
    Some(_) => acc.clone(),
    std::option::Option::None => match crate::v2_std_qualified_name::declaration_reference_path_optional(e.target.clone()) {
    std::option::Option::None => Rc::new(ResolveRequirementScan {
    seen: acc.seen.clone(),
    refusal: crate::std_optional::optional_present(resolve_requirement_diagnostic("resolve_reason_requirement_not_a_resource".to_string(), e.target.clone())),
}),
    Some(path) => if !crate::v2_std_symbol_index::symbol_index_declares_resource_at(index.clone(), path.clone()) {
        Rc::new(ResolveRequirementScan {
    seen: acc.seen.clone(),
    refusal: crate::std_optional::optional_present(resolve_requirement_diagnostic("resolve_reason_requirement_not_a_resource".to_string(), e.target.clone())),
})
    } else {
        if acc.seen.clone().iter().cloned().fold(false, |found: bool, p: QualifiedName| (found || (p.clone() == path.clone()))) {
            Rc::new(ResolveRequirementScan {
    seen: acc.seen.clone(),
    refusal: crate::std_optional::optional_present(resolve_requirement_diagnostic("resolve_reason_requirement_repeated".to_string(), e.target.clone())),
})
        } else {
            Rc::new(ResolveRequirementScan {
    seen: crate::std_algebra::list_snoc_item(acc.seen.clone(), path.clone()),
    refusal: crate::std_optional::optional_absent(),
})
        }
    },
},
}).refusal.clone()
}

