pub fn resolve_bind_positional_edges(ctx: Rc<ResolveContext>, edges: Rc<Vec<Rc<Edge>>>, scope_outer: Rc<Scope>, scope_inner: Rc<Scope>) -> Rc<ChildWalk> {
    {
        let arity = (edges.clone().len() as i64);
edges.iter().cloned().fold(child_walk_init(), |acc: Rc<ChildWalk>, e: Rc<Edge>| match crate::v2_std_node::bind_positional_slot_in_arity(acc.ordinal.clone(), arity.clone()) {
    Some(BindSlot::BindBinderSlot) => child_walk_step_prerequisite(acc.clone(), e.clone(), resolve_bind_binder_target(e.target.clone())),
    Some(BindSlot::BindValueSlot) => child_walk_step(acc.clone(), e.clone(), resolve_node_walk(resolve_ctx_with_scope(ctx.clone(), scope_outer.clone()), e.target.clone())),
    Some(BindSlot::BindBodySlot) => if acc.scope_prerequisite_refused.clone() {
            child_walk_unobservable(acc.clone(), "resolve_observation_bind_scope_prerequisite_refused".to_string())
        } else {
            child_walk_step(acc.clone(), e.clone(), resolve_node_walk(resolve_ctx_with_scope(ctx.clone(), scope_inner.clone()), e.target.clone()))
        },
    std::option::Option::None => child_walk_step(acc.clone(), e.clone(), resolve_node_walk(resolve_ctx_with_scope(ctx.clone(), scope_outer.clone()), e.target.clone())),
})
}
}

pub fn resolve_bind_edges(ctx: Rc<ResolveContext>, edges: Rc<Vec<Rc<Edge>>>, scope_outer: Rc<Scope>, scope_inner: Rc<Scope>) -> Rc<ChildWalk> {
    crate::v2_std_node::named_edges(edges.clone()).iter().cloned().fold(resolve_bind_positional_edges(ctx.clone(), crate::v2_std_node::positional_edges(edges.clone()), scope_outer.clone(), scope_inner), |acc: Rc<ChildWalk>, e: Rc<Edge>| if crate::v2_std_type_binder::edge_is_type_annotation(e.clone()) {
        child_walk_step(acc, e.clone(), resolve_type_role_target(ctx.clone(), e.target.clone()))
    } else {
        child_walk_step(acc, e.clone(), resolve_node_walk(resolve_ctx_with_scope(ctx.clone(), scope_outer.clone()), e.target.clone()))
    })
}

pub fn resolve_bind_node(ctx: Rc<ResolveContext>, n: Rc<Node>) -> Rc<ResolveNodeWalk> {
    if crate::v2_compiler_lexical_scope::bind_carries_arm_scope_exit(n.clone()) {
        resolve_walk_refused_one(crate::v2_std_diagnostic::diagnostics_singleton(malformed_tree_diagnostic(n.clone())))
    } else {
        if (crate::v2_std_node::positional_child_count(n.children.clone()) == 3) {
            match (*gate_value_binders(bind_binder_name_list(n.clone()), ctx.scope.clone(), n.clone())).clone() {
    BinderGate::BinderGateRefused { diagnostic: d, .. } => resolve_walk_refused_one(crate::v2_std_diagnostic::diagnostics_singleton(d.clone())),
    BinderGate::BinderGateAdmitted => child_walk_node(resolve_bind_edges(ctx.clone(), n.children.clone(), ctx.scope.clone(), lexical_frame(bind_frame_binders(n.clone()), ctx.scope.clone())), n.clone()),
}
        } else {
            if (crate::v2_std_node::positional_child_count(n.children.clone()) == 2) {
                child_walk_node(resolve_bind_edges(ctx.clone(), n.children.clone(), ctx.scope.clone(), ctx.scope.clone()), n.clone())
            } else {
                resolve_walk_refused_one(crate::v2_std_diagnostic::diagnostics_singleton(malformed_tree_diagnostic(n.clone())))
            }
        }
    }
}

pub fn resolve(tree: Rc<NormalizedTree>, lm: Rc<LanguageModel>) -> Rc<Outcome<Rc<ResolvedTree>>> {
    resolve_with_namespace(tree.clone(), build_program_namespace(tree.clone(), lm.clone()), lm.clone())
}

pub fn resolve_with_namespace(tree: Rc<NormalizedTree>, namespace: Rc<Namespace>, lm: Rc<LanguageModel>) -> Rc<Outcome<Rc<ResolvedTree>>> {
    resolve_with_namespace_policy(tree, namespace, lm, crate::v2_std_resolution_policy::default_name_resolution_policy())
}

pub fn resolve_with_namespace_policy(tree: Rc<NormalizedTree>, namespace: Rc<Namespace>, lm: Rc<LanguageModel>, policy: NameResolutionPolicy) -> Rc<Outcome<Rc<ResolvedTree>>> {
    match (*member_kind_channel_of_tree(tree.clone())).clone() {
    Outcome::Rejected { diagnostics: r, .. } => Rc::new(Outcome::Rejected {
    diagnostics: r.clone(),
}),
    Outcome::Accepted { value: channel, .. } => resolved_tree_outcome(resolve_walk_with_namespace_policy(tree.clone(), namespace.clone(), lm, policy), namespace.symbol_index.clone(), crate::v2_std_symbol_index::empty_symbol_index(), Rc::new(vec![]), empty_module_outcome_index(), channel.clone(), type_declaration_modifier_channel_of_tree(tree.clone())),
}
}

pub fn resolve_walk_with_namespace_policy(tree: Rc<NormalizedTree>, namespace: Rc<Namespace>, lm: Rc<LanguageModel>, policy: NameResolutionPolicy) -> Rc<ResolveNodeWalk> {
    if (crate::v2_std_node::well_formed(tree.root()) && crate::v2_std_type_binder::type_binder_labels_conform(tree.root())) {
        resolve_node_walk(resolve_ctx_init(namespace, lm, policy), tree.root())
    } else {
        resolve_walk_refused_one(crate::v2_std_diagnostic::diagnostics_singleton(malformed_tree_diagnostic(if crate::v2_std_node::well_formed(tree.root()) {
            match crate::v2_std_type_binder::type_binder_first_mislabelled(tree.root()) {
    Some(at) => at.clone(),
    std::option::Option::None => tree.root(),
}
        } else {
            tree.root()
        })))
    }
}

pub fn resolve_optional_declaration_refusal_optional(ctx: Rc<ResolveContext>, at: Rc<Node>) -> Option<Rc<Diagnostic>> {
    match crate::v2_std_symbol_index::symbol_index_lookup(ctx.namespace.symbol_index.clone(), crate::v2_std_qualified_name::optional_declaration_identity()) {
    std::option::Option::None => crate::std_optional::optional_present(resolve_type_application_diagnostic("resolve_reason_optional_declaration_unavailable".to_string(), at.clone())),
    Some(decl) => if optional_declaration_backs_optional(ctx.clone(), decl.clone()) {
        crate::std_optional::optional_absent()
    } else {
        crate::std_optional::optional_present(resolve_type_application_diagnostic("resolve_reason_optional_declaration_incompatible".to_string(), at.clone()))
    },
}
}

pub fn resolve_optional_application_contract_refusal_optional(ctx: Rc<ResolveContext>, n: Rc<Node>) -> Option<Rc<Diagnostic>> {
    { let __fm = crate::v2_std_node::positional_child_target_nodes(n.clone()); if __fm.len() == 2 { match crate::v2_std_qualified_name::declaration_denotation_of_type(n.clone()) {
    Some(denotation) => if crate::v2_std_qualified_name::declaration_denotation_is_optional(denotation.clone()) {
        resolve_optional_declaration_refusal_optional(ctx, n.clone())
    } else {
        crate::std_optional::optional_absent()
    },
    std::option::Option::None => crate::std_optional::optional_absent(),
} } else { crate::std_optional::optional_absent() } }
}

pub fn optional_declaration_backs_optional(ctx: Rc<ResolveContext>, decl: Rc<Node>) -> bool {
    match crate::v2_std_symbol_index::symbol_index_declared_binders_at(ctx.namespace.symbol_index.clone(), crate::v2_std_qualified_name::optional_declaration_identity()) {
    Some(binders) => { let __fm = crate::v2_std_type_binder::binder_conj_names(binders.clone()); if __fm.len() == 1 { let param = (*__fm)[0].clone(); match (*crate::v2_std_type_binder::type_decl_view(decl)).clone() {
    TypeDeclView::PlainTypeDecl { member: m, .. } => optional_member_backs_optional(m.clone(), param.clone()),
    TypeDeclView::GenericTypeDecl { member: m, .. } => optional_member_backs_optional(m.clone(), param.clone()),
    _ => false,
} } else { false } },
    std::option::Option::None => false,
}
}

pub fn optional_member_backs_optional(member: Rc<Node>, param: std::string::String) -> bool {
    (((crate::v2_std_node_query::node_is_coproduct(member.clone()) && ((member.children.clone().len() as i64) == 2)) && optional_arm_holds(member.clone(), "Absent".to_string(), param.clone())) && optional_arm_holds(member.clone(), "Present".to_string(), param.clone()))
}

pub fn optional_arm_holds(member: Rc<Node>, arm: std::string::String, param: std::string::String) -> bool {
    match optional_arm_target(member, arm.clone()) {
    Some(payload) => if crate::v2_std_node::symbol_eq(arm.clone(), "Absent".to_string()) {
        optional_arm_is_nullary(payload.clone())
    } else {
        optional_arm_carries_the_parameter(payload.clone(), param)
    },
    std::option::Option::None => false,
}
}

pub fn optional_arm_target(member: Rc<Node>, arm: std::string::String) -> Option<Rc<Node>> {
    member.children.clone().iter().cloned().fold(crate::std_optional::optional_absent(), |acc: Option<_>, e: Rc<Edge>| match acc.clone() {
    Some(_) => acc.clone(),
    std::option::Option::None => match (*e.label.clone()).clone() {
    EdgeLabel::Authored { name: name, .. } => if crate::v2_std_node::symbol_eq(name.clone(), arm.clone()) {
        crate::std_optional::optional_present(e.target.clone())
    } else {
        crate::std_optional::optional_absent()
    },
    _ => crate::std_optional::optional_absent(),
},
})
}

pub fn optional_arm_is_nullary(payload: Rc<Node>) -> bool {
    match (*payload.kind.clone()).clone() {
    NodeKind::TypeNode { connective: ref __rc_connective, .. } if matches!(__rc_connective.as_ref(), Connective::Conj) => { let Connective::Conj = __rc_connective.as_ref() else { unreachable!() }; ((payload.children.clone().len() as i64) == 0) },
    _ => false,
}
}

pub fn optional_type_names_parameter(type_node: Rc<Node>, param: std::string::String) -> bool {
    match (*type_node.kind.clone()).clone() {
    NodeKind::TypeNode { connective: ref __rc_connective, .. } if matches!(__rc_connective.as_ref(), Connective::Atom { identity: _, .. }) => { let Connective::Atom { identity: id, .. } = __rc_connective.as_ref() else { unreachable!() }; crate::v2_std_node::symbol_eq(id.clone(), param) },
    _ => false,
}
}

pub fn optional_arm_carries_the_parameter(payload: Rc<Node>, param: std::string::String) -> bool {
    match (*payload.kind.clone()).clone() {
    NodeKind::TypeNode { connective: ref __rc_connective, .. } if matches!(__rc_connective.as_ref(), Connective::Conj) => { let Connective::Conj = __rc_connective.as_ref() else { unreachable!() }; { let __fm = crate::v2_std_node_query::declared_field_list(payload.clone()); if __fm.len() == 1 { let field = (*__fm)[0].clone(); ((((payload.children.clone().len() as i64) == 1) && crate::v2_std_node::symbol_eq(field.name.clone(), "value".to_string())) && optional_type_names_parameter(field.type_node.clone(), param)) } else { false } } },
    _ => false,
}
}

